  it('applies standard tier discount (0) when no explicit discount provided', () => {
    const result = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 0);
