  it('explicit 0 discount overrides tier discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 0);
  });

  it('explicit discount overrides tier discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 10);
  });

  it('applies tier discount to multiple lines without explicit discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 5);
    assert.equal(result.value.lines[1].discountPercent, 5);
