23	export function createInvoice({ customerId, issueDate, lines }) {
24	  const customerResult = getCustomer(customerId);
25	  if (!customerResult.ok) return customerResult;
26	
27	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
28	
29	  if (!lines || lines.length === 0) return fail('NO_LINES');
30	
31	  const customer = customerResult.value;
32	  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
33	
34	  const processedLines = [];
35	  for (const line of lines) {
36	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
37	
38	    const discount = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
39	    if (!isValidDiscount(discount)) return fail('DISCOUNT_INVALID');
40	
41	    const productResult = getProduct(line.sku);
42	    if (!productResult.ok) return productResult;
43	
44	    const product = productResult.value;
45	    processedLines.push({
46	      sku: line.sku,
47	      name: product.name,
48	      qty: line.qty,
49	      unitPrice: product.unitPrice,
50	      vatRate: product.vatRate,
51	      discountPercent: discount,
52	    });
53	  }
54	
55	  return ok({
56	    customerId,
